  simpa [and_comm]
  using Subset.antisymm (fun x ⟨xs, xt⟩ ↦ ⟨xt, xs⟩) (fun x ⟨xt, xs⟩ ↦ ⟨xs, xt⟩)

theorem t4 : s ∩ (s ∪ t) = s := by
  apply le_anti (fun _ ⊢ environally _)
  constructor
  · { }
  · { intro xs; exact ⟨xs, left⟩ }

